const MEALS=[{id:'breakfast',name:'Śniadanie',icon:'breakfast',hint:'7:00–10:00'},{id:'secondBreakfast',name:'II śniadanie',icon:'secondBreakfast',hint:'10:00–12:00'},{id:'lunch',name:'Lunch',icon:'lunch',hint:'12:00–14:00'},{id:'mainMeal',name:'Obiad',icon:'mainMeal',hint:'14:00–17:00'},{id:'snack',name:'Przekąska',icon:'snack',hint:'W ciągu dnia'},{id:'dinner',name:'Kolacja',icon:'dinner',hint:'18:00–21:00'}];
const normalize=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const dateKey=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const today=new Date();
const defaults={dataVersion:4,theme:'dark',accent:'violet',selectedDate:dateKey(today),goal:2200,macroGoals:{p:135,c:263,f:67},water:0,waterGoal:2500,activityKcal:0,diary:{},customProducts:[],recent:[],profile:{sex:'male',age:25,height:180,weight:75,activity:1.55,adjustment:0},weights:[],onboardingComplete:false,offlineMode:false,user:null,accountUid:null};
let stored={};try{stored=JSON.parse(localStorage.getItem('kalorio-state')||'{}')}catch{}
let state={...defaults,...stored};
if(!stored.dataVersion||stored.dataVersion<3){state={...state,dataVersion:3,diary:{},water:0,activityKcal:0,recent:[],weights:[],onboardingComplete:false,offlineMode:false}}
state.dataVersion=4;state.diary=state.diary||{};state.customProducts=state.customProducts||[];state.recent=state.recent||[];state.macroGoals=state.macroGoals||defaults.macroGoals;state.profile={...defaults.profile,...(state.profile||{})};
let selectedMeal='breakfast',activeCategory='Wszystkie',currentProduct=null,currentAnalysis=null,selectedPhotoFile=null,toastTimer,auth=null,firebaseUser=null,aiModel=null,aiFallbackModel=null,firebaseAuthApi=null,firebaseFirestoreApi=null,db=null,appCheck=null,firebaseAppCheckApi=null,cloudSyncReady=false,cloudSyncBusy=false,cloudSyncTimer=null;
const allProducts=()=>[...state.customProducts,...PRODUCTS];
const getProduct=id=>allProducts().find(p=>p.id===id);
const save=()=>{localStorage.setItem('kalorio-state',JSON.stringify(state));queueCloudSync()};
const fmt=n=>Math.round(n).toLocaleString('pl-PL');
const one=n=>Number(n).toLocaleString('pl-PL',{maximumFractionDigits:1});
const nutrient=(p,g,key)=>p?(p[key]*g/100):0;
const ensureDay=()=>{const k=state.selectedDate;if(!state.diary[k])state.diary[k]={};MEALS.forEach(m=>{if(!Array.isArray(state.diary[k][m.id]))state.diary[k][m.id]=[]});return state.diary[k]};
const totals=()=>Object.values(ensureDay()).flat().reduce((a,item)=>{const p=getProduct(item.productId);if(p){a.kcal+=nutrient(p,item.grams,'kcal');a.p+=nutrient(p,item.grams,'p');a.c+=nutrient(p,item.grams,'c');a.f+=nutrient(p,item.grams,'f')}return a},{kcal:0,p:0,c:0,f:0});

function showToast(msg){clearTimeout(toastTimer);document.getElementById('toastText').textContent=msg;document.getElementById('toast').classList.add('show');toastTimer=setTimeout(()=>document.getElementById('toast').classList.remove('show'),2400)}
function switchView(name){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));window.scrollTo({top:0,behavior:'smooth'});closeModals();if(name==='food')renderProducts();if(name==='progress')renderProgress()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
document.querySelectorAll('[data-view-link]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();switchView(b.dataset.viewLink)}));

const themeColors={violet:{dark:'#0c0913',light:'#f7f3ff'},ocean:{dark:'#071018',light:'#f1f8fc'},sunset:{dark:'#130c08',light:'#fff7f0'},rose:{dark:'#14090f',light:'#fff3f8'},lime:{dark:'#090c0b',light:'#f4f6f3'}};
function syncThemeColor(){const accent=document.documentElement.dataset.accent||'violet',theme=document.documentElement.dataset.theme||'dark';document.querySelector('meta[name="theme-color"]').content=themeColors[accent]?.[theme]||themeColors.violet[theme]}
function setTheme(theme){state.theme=theme;let actual=theme;if(theme==='system')actual=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.documentElement.dataset.theme=actual;syncThemeColor();document.querySelectorAll('[data-theme-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.themeChoice===theme));document.querySelectorAll('.theme-toggle span:last-child').forEach(s=>s.textContent=actual==='dark'?'Jasny motyw':'Ciemny motyw');save()}
setTheme(state.theme||'dark');
document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')));
document.querySelectorAll('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>setTheme(b.dataset.themeChoice)));
function setAccent(accent){state.accent=accent||'violet';document.documentElement.dataset.accent=state.accent;syncThemeColor();document.querySelectorAll('[data-accent-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.accentChoice===state.accent));save()}
setAccent(state.accent);
document.querySelectorAll('[data-accent-choice]').forEach(b=>b.addEventListener('click',()=>setAccent(b.dataset.accentChoice)));

function renderWeekStrip(){const selected=new Date(`${state.selectedDate}T12:00:00`),monday=new Date(selected),day=(selected.getDay()+6)%7;monday.setDate(selected.getDate()-day);const strip=document.getElementById('weekStrip');strip.innerHTML=Array.from({length:7},(_,index)=>{const d=new Date(monday);d.setDate(monday.getDate()+index);const key=dateKey(d),hasEntries=kcalForDate(key)>0,isSelected=key===state.selectedDate;return `<button class="week-day ${isSelected?'selected':''} ${hasEntries?'logged':''}" data-week-date="${key}" aria-label="${d.toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'})}"><span>${d.toLocaleDateString('pl-PL',{weekday:'narrow'})}</span><b>${d.getDate()}</b><i></i></button>`}).join('');strip.querySelectorAll('[data-week-date]').forEach(button=>button.onclick=()=>{state.selectedDate=button.dataset.weekDate;save();updateDate()})}
function updateDate(){const d=new Date(`${state.selectedDate}T12:00:00`),isToday=dateKey(today)===state.selectedDate;document.getElementById('dateTitle').textContent=isToday?'Dzisiaj':d.toLocaleDateString('pl-PL',{day:'numeric',month:'long'});document.getElementById('dateLong').textContent=d.toLocaleDateString('pl-PL',{day:'numeric',month:'long',weekday:'long'});renderWeekStrip();renderDashboard()}
document.getElementById('prevDay').onclick=()=>{const d=new Date(`${state.selectedDate}T12:00:00`);d.setDate(d.getDate()-1);state.selectedDate=dateKey(d);save();updateDate()};
document.getElementById('nextDay').onclick=()=>{const d=new Date(`${state.selectedDate}T12:00:00`);d.setDate(d.getDate()+1);state.selectedDate=dateKey(d);save();updateDate()};

function iconSvg(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`}
function renderDashboard(){const t=totals(),remaining=Math.max(0,state.goal+state.activityKcal-t.kcal),pct=Math.min(100,t.kcal/(state.goal+state.activityKcal)*100);document.getElementById('remainingKcal').textContent=fmt(remaining);document.getElementById('eatenKcal').textContent=fmt(t.kcal);document.getElementById('goalKcal').textContent=fmt(state.goal);document.getElementById('activityKcal').textContent=fmt(state.activityKcal);document.getElementById('calorieRing').style.setProperty('--pct',`${pct}%`);document.getElementById('balanceStatus').textContent=pct>110?'Powyżej celu':pct>=90?'Cel prawie gotowy':'W dobrym rytmie';[['protein','p'],['carbs','c'],['fat','f']].forEach(([id,key])=>{const value=t[key],goal=state.macroGoals[key],percent=Math.min(100,value/goal*100);document.getElementById(`${id}Value`).textContent=fmt(value);document.getElementById(`${id}Goal`).textContent=fmt(goal);document.getElementById(`${id}Percent`).textContent=`${Math.round(percent)}%`;document.getElementById(`${id}Bar`).style.width=`${percent}%`});renderMeals();renderWater();const gap=Math.max(0,state.macroGoals.p-t.p);document.querySelector('.insight-card h3').textContent=gap?`Jeszcze ${fmt(gap)} g białka`:'Cel białka osiągnięty'}
function renderMeals(){const day=ensureDay(),list=document.getElementById('mealList');list.innerHTML=MEALS.map((meal,index)=>{const items=day[meal.id]||[],sum=items.reduce((a,i)=>a+nutrient(getProduct(i.productId),i.grams,'kcal'),0),countLabel=items.length===1?'produkt':items.length>=2&&items.length<=4?'produkty':'produktów';return `<article class="meal-card" style="--meal-index:${index}"><div class="meal-head"><span class="meal-icon ${meal.id}">${iconSvg(meal.icon)}</span><span class="meal-title"><b>${meal.name}</b><span>${items.length?`${items.length} ${countLabel}`:meal.hint}</span></span><span class="meal-kcal"><b>${fmt(sum)} kcal</b><span>${items.length?'wpisane':'brak wpisów'}</span></span><div class="meal-actions"><button class="meal-ai" data-meal-ai="${meal.id}" aria-label="Dodaj przez AI do: ${meal.name}">${iconSvg('sparkles')}</button><button class="meal-add" data-meal-add="${meal.id}" aria-label="Dodaj do: ${meal.name}">${iconSvg('plus')}</button></div></div>${items.length?`<div class="meal-items">${items.map(i=>{const p=getProduct(i.productId);return p?`<div class="meal-item"><span class="meal-item-info"><b>${p.name}</b><span>${one(i.grams)} g · B ${one(nutrient(p,i.grams,'p'))} · W ${one(nutrient(p,i.grams,'c'))} · T ${one(nutrient(p,i.grams,'f'))}</span></span><strong>${fmt(nutrient(p,i.grams,'kcal'))} kcal</strong><button class="remove-item" data-remove="${i.id}" data-from="${meal.id}" aria-label="Usuń">${iconSvg('trash')}</button></div>`:''}).join('')}</div>`:`<div class="empty-meal">Dodaj pierwszy produkt do tego posiłku</div>`}</article>`}).join('');list.querySelectorAll('[data-meal-add]').forEach(b=>b.onclick=()=>openAdd(b.dataset.mealAdd));list.querySelectorAll('[data-meal-ai]').forEach(b=>b.onclick=()=>{selectedMeal=b.dataset.mealAi;switchView('ai');setTimeout(()=>document.getElementById('aiText').focus(),180)});list.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{day[b.dataset.from]=day[b.dataset.from].filter(i=>i.id!==b.dataset.remove);save();renderDashboard();showToast('Usunięto produkt')})}
function renderWater(){const p=Math.min(100,state.water/state.waterGoal*100);document.getElementById('waterValue').textContent=(state.water/1000).toLocaleString('pl-PL',{minimumFractionDigits:2});document.getElementById('waterGoal').textContent=(state.waterGoal/1000).toLocaleString('pl-PL',{minimumFractionDigits:2});document.getElementById('waterPercent').textContent=`${Math.round(p)}%`;document.getElementById('waterBar').style.width=`${p}%`}
document.querySelectorAll('[data-water]').forEach(b=>b.onclick=()=>{state.water=Math.max(0,Math.min(5000,state.water+Number(b.dataset.water)));save();renderWater();showToast(Number(b.dataset.water)>0?'Dodano szklankę wody':'Zaktualizowano wodę')});

function renderProducts(){const q=normalize(document.getElementById('foodSearch').value),items=allProducts().filter(p=>(activeCategory==='Wszystkie'||p.cat===activeCategory)&&normalize(`${p.name} ${p.brand} ${p.keys||''}`).includes(q));document.getElementById('resultCount').textContent=`${items.length} produktów`;document.getElementById('productGrid').innerHTML=items.length?items.map(productCard).join(''):'<div class="no-results">Nie znaleźliśmy takiego produktu. Dodaj go jako własny.</div>';document.querySelectorAll('.product-card').forEach(b=>b.onclick=()=>openProduct(b.dataset.product));renderRecent()}
function productCard(p){return `<button class="product-card" data-product="${p.id}"><span class="food-emoji">${p.emoji||'🥗'}</span><span><b>${p.name}</b><small>${p.brand} · B ${one(p.p)} · W ${one(p.c)} · T ${one(p.f)}</small></span><strong>${fmt(p.kcal)}<span>kcal / 100 g</span></strong></button>`}
const cats=['Wszystkie',...new Set(PRODUCTS.map(p=>p.cat))];document.getElementById('categoryFilters').innerHTML=cats.map(c=>`<button class="${c==='Wszystkie'?'active':''}" data-cat="${c}">${c}</button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x===b));renderProducts()});document.getElementById('foodSearch').oninput=renderProducts;
function renderRecent(){const items=state.recent.map(getProduct).filter(Boolean).slice(0,5);document.getElementById('recentProducts').innerHTML=items.map(p=>`<div class="recent-item"><span class="food-emoji">${p.emoji||'🥗'}</span><span><b>${p.name}</b><small>${fmt(p.kcal)} kcal / 100 g</small></span><button data-recent="${p.id}" aria-label="Dodaj">${iconSvg('plus')}</button></div>`).join('');document.querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>openProduct(b.dataset.recent))}

function openModal(id){document.getElementById('modalBackdrop').classList.add('active');document.getElementById(id).classList.add('active');document.body.style.overflow='hidden'}
function closeModals(){document.querySelectorAll('.modal,.sheet').forEach(m=>m.classList.remove('active'));document.getElementById('modalBackdrop').classList.remove('active');document.body.style.overflow=''}
document.getElementById('modalBackdrop').onclick=closeModals;document.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModals);
function openAdd(meal='breakfast'){selectedMeal=meal;renderMealTabs();renderSheetProducts();openModal('addSheet')}
document.querySelectorAll('[data-open-add]').forEach(b=>b.onclick=()=>openAdd('breakfast'));
function renderMealTabs(){document.getElementById('mealTabs').innerHTML=MEALS.map(m=>`<button data-meal-tab="${m.id}" class="${m.id===selectedMeal?'active':''}">${m.name}</button>`).join('');document.querySelectorAll('[data-meal-tab]').forEach(b=>b.onclick=()=>{selectedMeal=b.dataset.mealTab;renderMealTabs()})}
function renderSheetProducts(){const q=normalize(document.getElementById('sheetSearch').value),items=allProducts().filter(p=>normalize(`${p.name} ${p.keys||''}`).includes(q)).slice(0,6);document.getElementById('sheetProducts').innerHTML=items.map(p=>`<button class="sheet-product" data-sheet-product="${p.id}"><b>${p.emoji||'🥗'} ${p.name}</b><span>${fmt(p.kcal)} kcal / 100 g</span></button>`).join('');document.querySelectorAll('[data-sheet-product]').forEach(b=>b.onclick=()=>openProduct(b.dataset.sheetProduct))}
document.getElementById('sheetSearch').oninput=renderSheetProducts;
document.querySelectorAll('[data-add-mode]').forEach(b=>b.onclick=()=>{const m=b.dataset.addMode;closeModals();if(m==='search')switchView('food');if(m==='ai')switchView('ai');if(m==='custom')openModal('customModal')});
document.getElementById('openCustomProduct').onclick=()=>openModal('customModal');

function openProduct(id){currentProduct=getProduct(id);if(!currentProduct)return;closeModals();document.getElementById('modalProductName').textContent=currentProduct.name;document.getElementById('modalProductBrand').textContent=`${currentProduct.brand} · wartości na 100 g`;document.getElementById('modalEmoji').textContent=currentProduct.emoji||'🥗';document.getElementById('portionValue').value=100;document.getElementById('modalMeal').innerHTML=MEALS.map(m=>`<option value="${m.id}" ${m.id===selectedMeal?'selected':''}>${m.name}</option>`).join('');updateProductModal();openModal('productModal')}
function updateProductModal(){if(!currentProduct)return;const g=Math.max(1,Number(document.getElementById('portionValue').value)||0);document.getElementById('modalKcal').textContent=fmt(nutrient(currentProduct,g,'kcal'));document.getElementById('modalProtein').textContent=`${one(nutrient(currentProduct,g,'p'))} g`;document.getElementById('modalCarbs').textContent=`${one(nutrient(currentProduct,g,'c'))} g`;document.getElementById('modalFat').textContent=`${one(nutrient(currentProduct,g,'f'))} g`}
document.getElementById('portionValue').oninput=updateProductModal;document.getElementById('portionMinus').onclick=()=>{const i=document.getElementById('portionValue');i.value=Math.max(1,Number(i.value)-10);updateProductModal()};document.getElementById('portionPlus').onclick=()=>{const i=document.getElementById('portionValue');i.value=Number(i.value)+10;updateProductModal()};
document.getElementById('confirmProduct').onclick=()=>{const day=ensureDay(),meal=document.getElementById('modalMeal').value,g=Math.max(1,Number(document.getElementById('portionValue').value));day[meal].push({id:crypto.randomUUID(),productId:currentProduct.id,grams:g});state.recent=[currentProduct.id,...state.recent.filter(x=>x!==currentProduct.id)].slice(0,6);save();closeModals();renderDashboard();showToast(`Dodano: ${currentProduct.name}`)};
document.getElementById('customForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));const p={id:`custom-${Date.now()}`,name:d.name,brand:d.brand||'własny produkt',cat:'Własne',emoji:'🥗',kcal:Number(d.kcal),p:Number(d.protein),c:Number(d.carbs),f:Number(d.fat),keys:''};state.customProducts.unshift(p);save();e.currentTarget.reset();closeModals();renderProducts();showToast('Własny produkt został zapisany')};

const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const AI_PROMPT=`Jesteś precyzyjnym polskim analizatorem żywienia. Analizujesz jeden posiłek i zwracasz wyłącznie dane zgodne ze schematem JSON.
Zasady krytyczne:
1. Nie podmieniaj produktów na inne. Zachowuj nazwy, marki, smaki, procent tłuszczu i rodzaj produktu z opisu (np. Whey WPC, mleko 3,2%, Human Protect biała czekolada-malina).
2. Nie dodawaj składników, których użytkownik nie wymienił albo których nie widać na zdjęciu. Nigdy nie zwracaj kurczaka z ryżem, jeśli brak na to dowodu.
3. Użyj podanych gramów i mililitrów. Dla mleka przyjmij 1 ml ≈ 1 g. Jeśli ilości brakuje, oszacuj typową porcję, obniż confidence i opisz założenie w notes.
4. kcal i makro dla każdego składnika dotyczą wpisanej porcji, nie 100 g. totals muszą być sumą składników.
5. Przy zdjęciu zaznacz niepewne rozpoznania w notes. Jeśli zdjęcie nie przedstawia jedzenia, zwróć pustą listę składników.
6. Kalorie są szacunkiem; preferuj wartości charakterystyczne dla dokładnej marki/odmiany, jeśli została podana.`;

function analysisValues(){return [...document.querySelectorAll('[data-ai-grams]')].map(input=>{const i=currentAnalysis.ingredients[Number(input.dataset.aiGrams)],grams=Math.max(0,Number(input.value)||0),factor=i.amount_g?grams/i.amount_g:0;return{...i,amount_g:grams,kcal:i.kcal*factor,protein_g:i.protein_g*factor,carbs_g:i.carbs_g*factor,fat_g:i.fat_g*factor}})}
function updateAnalysisTotals(){const items=analysisValues(),total=items.reduce((a,i)=>({kcal:a.kcal+i.kcal,p:a.p+i.protein_g,c:a.c+i.carbs_g,f:a.f+i.fat_g}),{kcal:0,p:0,c:0,f:0});items.forEach((i,index)=>{const kcal=document.querySelector(`[data-ai-kcal="${index}"]`);if(kcal)kcal.textContent=`${fmt(i.kcal)} kcal`});document.getElementById('analysisTotalKcal').textContent=`${fmt(total.kcal)} kcal`;document.getElementById('analysisTotalMacro').textContent=`B ${one(total.p)} g · W ${one(total.c)} g · T ${one(total.f)} g`}
function showAiAnalysis(data,label){currentAnalysis=data;const box=document.getElementById('analysisResult');box.classList.remove('hidden');if(!data.ingredients?.length){box.innerHTML=`<div class="analysis-head"><div><p class="eyebrow">${esc(label)}</p><h2>Nie rozpoznano posiłku</h2></div></div><p class="muted">Model nie znalazł wiarygodnych składników. Dodaj wyraźniejsze zdjęcie albo dokładniejszy opis — nie będziemy zgadywać.</p>`;return}const confidence=Math.round(Math.max(0,Math.min(1,Number(data.confidence)||0))*100);box.innerHTML=`<div class="analysis-head"><div><p class="eyebrow">${esc(label)}</p><h2>${esc(data.meal_name||'Rozpoznany posiłek')}</h2></div><span class="confidence">pewność ${confidence}%</span></div>${(data.notes||[]).length?`<div class="ai-notes">${data.notes.map(n=>`<p><span data-icon="info"></span>${esc(n)}</p>`).join('')}</div>`:''}<div class="analysis-items">${data.ingredients.map((i,index)=>`<div class="analysis-item editable"><span><b>${esc(i.name)}</b><small>${esc(i.brand||'')}</small></span><label><input type="number" min="0" step="1" value="${Math.round(i.amount_g)}" data-ai-grams="${index}"><em>g</em></label><strong data-ai-kcal="${index}">${fmt(i.kcal)} kcal</strong></div>`).join('')}</div><div class="analysis-total"><div><span class="muted">Razem</span><strong id="analysisTotalKcal">0 kcal</strong><small id="analysisTotalMacro">B 0 g · W 0 g · T 0 g</small></div><div class="analysis-actions"><button class="secondary-btn" id="retryAnalysis">Analizuj ponownie</button><button class="primary-btn" id="addAnalysis">Dodaj do dziennika</button></div></div>`;box.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=iconSvg(el.dataset.icon));box.querySelectorAll('[data-ai-grams]').forEach(i=>i.oninput=updateAnalysisTotals);document.getElementById('retryAnalysis').onclick=()=>box.classList.add('hidden');document.getElementById('addAnalysis').onclick=()=>{const day=ensureDay(),items=analysisValues().filter(i=>i.amount_g>0);items.forEach(i=>{const id=`ai-${Date.now()}-${crypto.randomUUID().slice(0,8)}`,grams=i.amount_g,per100=100/grams;state.customProducts.unshift({id,name:i.name,brand:i.brand||'oszacowane przez AI',cat:'AI',emoji:'✨',kcal:i.kcal*per100,p:i.protein_g*per100,c:i.carbs_g*per100,f:i.fat_g*per100,keys:i.name});day[selectedMeal].push({id:crypto.randomUUID(),productId:id,grams})});save();renderDashboard();switchView('today');showToast(`Dodano ${items.length} ${items.length===1?'składnik':'składniki'}`)};updateAnalysisTotals();box.scrollIntoView({behavior:'smooth',block:'center'})}
function aiErrorMessage(error){const raw=`${error?.code||''} ${error?.message||''}`.toLowerCase();if(/app.?check|401|403|unauthenticated|permission.denied/.test(raw))return'Firebase App Check nie zwrócił poprawnego tokenu. Sprawdź w Firebase: App Check → APIs → Firebase AI Logic.';if(error?.name==='TimeoutError'||error?.name==='AbortError')return'Firebase AI nie odpowiedział na żadnym z dwóch modeli. To problem połączenia usługi lub ustawień App Check, a nie opisu posiłku.';if(/429|resource.?exhausted|quota/.test(raw))return'Limit zapytań AI został chwilowo wykorzystany. Odczekaj minutę i spróbuj ponownie.';if(/404|not.?found|model/.test(raw))return'Wybrany model AI nie jest dostępny dla tego projektu. Trzeba zmienić model w konfiguracji Firebase AI Logic.';if(/failed to fetch|network|offline|load failed/.test(raw))return'Przeglądarka nie mogła połączyć się z Firebase AI Logic. Otwórz aplikację bezpośrednio w Safari lub Chrome i spróbuj ponownie.';if(!aiModel)return'Prawdziwy model AI nie został uruchomiony. Aplikacja nie pokaże zmyślonego wyniku.';return'Firebase AI zwrócił błąd. Poniżej pokazujemy jego kod, żeby dało się ustalić dokładną przyczynę.'}
function showAiError(error,retry){const box=document.getElementById('analysisResult'),detail=error?.code||error?.message||'';box.classList.remove('hidden');box.innerHTML=`<div class="analysis-head"><div><p class="eyebrow">Asystent AI</p><h2>Nie udało się przeanalizować posiłku</h2></div></div><p class="muted">${esc(aiErrorMessage(error))}</p>${detail?`<small class="error-detail">Kod: ${esc(detail)}</small>`:''}${retry?'<button class="secondary-btn ai-retry" id="retryFailedAnalysis">Spróbuj ponownie</button>':''}`;if(retry)document.getElementById('retryFailedAnalysis').onclick=retry;box.scrollIntoView({behavior:'smooth',block:'center'})}
async function fileToPart(file){const prepared=await resizeImage(file);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(prepared)});return{inlineData:{data,mimeType:prepared.type||'image/jpeg'}}}
async function resizeImage(file){try{const bitmap=await createImageBitmap(file),max=1280,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Nie udało się przygotować zdjęcia')),'image/jpeg',.86))}catch{return file}}
function withDeadline(promise,timeout,message){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>{const error=new Error(message);error.name='TimeoutError';reject(error)},timeout)})]).finally(()=>clearTimeout(timer))}
async function requestModel(model,content,timeout=28000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{return await model.generateContent(content,{signal:controller.signal,timeout})}catch(error){if(error?.name==='AbortError'){const timeoutError=new Error('Model nie odpowiedział przed upływem limitu czasu');timeoutError.name='TimeoutError';throw timeoutError}throw error}finally{clearTimeout(timer)}}
async function analyzeMeal({description='',file=null}){if(!aiModel)throw new Error('Wymagane jest połączenie Firebase AI Logic.');const context=description?`Opis użytkownika (traktuj dosłownie):\n<<<${description}>>>`:'Przeanalizuj wyłącznie jedzenie widoczne na zdjęciu.';const content=file?[`${AI_PROMPT}\n\n${context}`,await fileToPart(file)]:`${AI_PROMPT}\n\n${context}`;if(appCheck&&firebaseAppCheckApi)await withDeadline(firebaseAppCheckApi.getToken(appCheck,false),12000,'App Check nie zwrócił tokenu');let result,lastError;for(const model of[aiModel,aiFallbackModel].filter(Boolean)){try{result=await requestModel(model,content);break}catch(error){lastError=error;console.warn('AI model fallback:',error)}}if(!result)throw lastError||new Error('Firebase AI nie zwrócił odpowiedzi');const parsed=JSON.parse(result.response.text());parsed.ingredients=(parsed.ingredients||[]).map(i=>({name:String(i.name||'Składnik'),brand:String(i.brand||''),amount_g:Number(i.amount_g)||0,kcal:Number(i.kcal)||0,protein_g:Number(i.protein_g)||0,carbs_g:Number(i.carbs_g)||0,fat_g:Number(i.fat_g)||0,confidence:Number(i.confidence)||0}));return parsed}
async function runAnalysis(button,task,label){const old=button.innerHTML;button.disabled=true;button.classList.add('loading');button.innerHTML='<span class="spinner"></span> Analizuję…';document.getElementById('analysisResult').classList.add('hidden');try{showAiAnalysis(await task(),label)}catch(error){console.error(error);showAiError(error,()=>runAnalysis(button,task,label))}finally{button.disabled=false;button.classList.remove('loading');button.innerHTML=old}}
document.getElementById('analyzeText').onclick=()=>{const text=document.getElementById('aiText').value.trim();if(!text)return showToast('Najpierw opisz swój posiłek');runAnalysis(document.getElementById('analyzeText'),()=>analyzeMeal({description:text}),'Analiza opisu')};
document.querySelectorAll('.example-chips button').forEach(b=>b.onclick=()=>{document.getElementById('aiText').value=b.textContent;document.getElementById('aiText').focus()});
document.getElementById('photoInput').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/'))return showToast('Wybierz plik ze zdjęciem');selectedPhotoFile=f;const url=URL.createObjectURL(f),wrap=document.getElementById('photoPreview');wrap.querySelector('img').src=url;wrap.classList.remove('hidden')};
document.getElementById('analyzePhoto').onclick=()=>{if(!selectedPhotoFile)return showToast('Najpierw dodaj zdjęcie');runAnalysis(document.getElementById('analyzePhoto'),()=>analyzeMeal({file:selectedPhotoFile}),'Analiza zdjęcia')};

function firebaseConfigured(){const c=window.KALORIO_FIREBASE_CONFIG;return Boolean(c?.apiKey&&c?.authDomain&&c?.projectId&&c?.appId)}
function setSyncStatus(text,tone=''){const el=document.getElementById('syncStatus');if(!el)return;el.textContent=text;el.dataset.tone=tone}
function cloudStateRef(){return db&&firebaseUser&&firebaseFirestoreApi?firebaseFirestoreApi.doc(db,'users',firebaseUser.uid,'private','appState'):null}
function statePayload(){return JSON.stringify({...state,dataVersion:4,accountUid:firebaseUser?.uid||state.accountUid})}
async function writeCloudState(create=false){const ref=cloudStateRef();if(!ref||cloudSyncBusy)return;cloudSyncBusy=true;setSyncStatus('Synchronizuję…','busy');try{const data={uid:firebaseUser.uid,schemaVersion:4,payload:statePayload(),updatedAt:firebaseFirestoreApi.serverTimestamp()};if(create)data.createdAt=firebaseFirestoreApi.serverTimestamp();await firebaseFirestoreApi.setDoc(ref,data,{merge:!create});setSyncStatus('Zapisano na koncie','ok')}catch(error){console.error('Cloud sync:',error);setSyncStatus(/permission-denied|not-found|failed-precondition/i.test(`${error?.code} ${error?.message}`)?'Włącz Firestore w Firebase':'Nie udało się zapisać w chmurze','error')}finally{cloudSyncBusy=false}}
function queueCloudSync(){if(!cloudSyncReady||!firebaseUser||!db)return;clearTimeout(cloudSyncTimer);setSyncStatus('Zmiany oczekują…','busy');cloudSyncTimer=setTimeout(()=>writeCloudState(false),800)}
function hydrateState(incoming){const next={...defaults,...(incoming||{})};next.dataVersion=4;next.diary=next.diary&&typeof next.diary==='object'?next.diary:{};next.customProducts=Array.isArray(next.customProducts)?next.customProducts:[];next.recent=Array.isArray(next.recent)?next.recent:[];next.weights=Array.isArray(next.weights)?next.weights:[];next.macroGoals={...defaults.macroGoals,...(next.macroGoals||{})};next.profile={...defaults.profile,...(next.profile||{})};return next}
function refreshApp(){setTheme(state.theme||'dark');setAccent(state.accent||'violet');loadProfile();renderIdentity();updateDate();renderProducts();renderProgress()}
async function loadCloudState(user){if(!db||!firebaseFirestoreApi){setSyncStatus('Chmura niedostępna','error');return}const previousUid=state.accountUid,ref=cloudStateRef();setSyncStatus('Pobieram dane konta…','busy');try{const snapshot=await firebaseFirestoreApi.getDoc(ref);if(snapshot.exists()){const record=snapshot.data(),remote=JSON.parse(record.payload||'{}');state=hydrateState(remote)}else if(previousUid&&previousUid!==user.uid){state=hydrateState({theme:state.theme,accent:state.accent,selectedDate:dateKey(today)})}state.accountUid=user.uid;state.user={name:user.displayName||'',displayName:user.displayName||'',email:user.email||'',photoURL:user.photoURL||''};state.offlineMode=false;localStorage.setItem('kalorio-state',JSON.stringify(state));if(!snapshot.exists())await writeCloudState(true);refreshApp();cloudSyncReady=true;setSyncStatus('Zapisano na koncie','ok')}catch(error){console.error('Cloud load:',error);state.accountUid=user.uid;state.user={name:user.displayName||'',displayName:user.displayName||'',email:user.email||'',photoURL:user.photoURL||''};localStorage.setItem('kalorio-state',JSON.stringify(state));refreshApp();cloudSyncReady=true;setSyncStatus(/permission-denied|not-found|failed-precondition/i.test(`${error?.code} ${error?.message}`)?'Włącz Firestore w Firebase':'Tryb lokalny — błąd chmury','error')}}
function showOnboarding(step='auth'){const onboarding=document.getElementById('onboarding');onboarding.classList.remove('hidden');document.body.classList.add('onboarding-open');document.getElementById('authStep').classList.toggle('hidden',step!=='auth');document.getElementById('setupStep').classList.toggle('hidden',step!=='setup')}
function hideOnboarding(){document.getElementById('onboarding').classList.add('hidden');document.body.classList.remove('onboarding-open')}
function renderIdentity(){const user=firebaseUser||state.user,name=user?.displayName||user?.name||'',first=name.trim().split(/\s+/)[0]||'',initial=(first[0]||'K').toUpperCase(),hour=new Date().getHours(),hello=hour<12?'Dzień dobry':hour<18?'Cześć':'Dobry wieczór';document.getElementById('greetingTitle').textContent=first?`${hello}, ${first}`:hello;document.getElementById('profileChipName').textContent=first||'Twój profil';document.getElementById('profileChipGoal').textContent=`Cel: ${state.profile.adjustment<0?'redukcja':state.profile.adjustment>0?'budowa masy':'utrzymanie'}`;document.querySelectorAll('.user-initial,.mobile-header .avatar').forEach(el=>el.textContent=initial);const accountAvatar=document.getElementById('accountAvatar');accountAvatar.innerHTML=user?.photoURL?`<img src="${esc(user.photoURL)}" alt="">`:initial;document.getElementById('accountName').textContent=name||'Konto lokalne';document.getElementById('accountEmail').textContent=user?.email||'Dane są zapisane tylko na tym urządzeniu';document.getElementById('signOutBtn').classList.toggle('hidden',!firebaseUser);if(!firebaseUser)setSyncStatus('Zapis lokalny')}
async function handleAuthUser(user){firebaseUser=user||null;cloudSyncReady=false;clearTimeout(cloudSyncTimer);if(user){renderIdentity();await loadCloudState(user);state.onboardingComplete?hideOnboarding():showOnboarding('setup')}else{renderIdentity();if(!state.offlineMode)showOnboarding('auth')}}
async function initFirebase(){
  document.getElementById('continueOffline').classList.toggle('hidden',firebaseConfigured());
  if(!firebaseConfigured()){
    if(!state.onboardingComplete)showOnboarding('auth');else hideOnboarding();
    renderIdentity();
    return;
  }
  try{
    const version='13.4.0';
    const [appApi,authApi,aiApi,appCheckApi,firestoreApi]=await Promise.all([
      import(`https://www.gstatic.com/firebasejs/${version}/firebase-app.js`),
      import(`https://www.gstatic.com/firebasejs/${version}/firebase-auth.js`),
      import(`https://www.gstatic.com/firebasejs/${version}/firebase-ai.js`),
      import(`https://www.gstatic.com/firebasejs/${version}/firebase-app-check.js`),
      import(`https://www.gstatic.com/firebasejs/${version}/firebase-firestore.js`)
    ]);
    const config=window.KALORIO_FIREBASE_CONFIG;
    const app=appApi.initializeApp(config);
    firebaseAppCheckApi=appCheckApi;
    appCheck=appCheckApi.initializeAppCheck(app,{provider:new appCheckApi.ReCaptchaEnterpriseProvider(config.appCheckSiteKey),isTokenAutoRefreshEnabled:true});
    firebaseAuthApi=authApi;
    firebaseFirestoreApi=firestoreApi;
    db=firestoreApi.getFirestore(app);
    auth=authApi.getAuth(app);
    await authApi.setPersistence(auth,authApi.browserLocalPersistence);
    await authApi.getRedirectResult(auth).catch(error=>{if(error.code!=='auth/no-auth-event')throw error});
    authApi.onAuthStateChanged(auth,handleAuthUser);
    const schema=aiApi.Schema.object({properties:{meal_name:aiApi.Schema.string(),confidence:aiApi.Schema.number(),needs_confirmation:aiApi.Schema.boolean(),notes:aiApi.Schema.array({items:aiApi.Schema.string()}),ingredients:aiApi.Schema.array({items:aiApi.Schema.object({properties:{name:aiApi.Schema.string(),brand:aiApi.Schema.string(),amount_g:aiApi.Schema.number(),kcal:aiApi.Schema.number(),protein_g:aiApi.Schema.number(),carbs_g:aiApi.Schema.number(),fat_g:aiApi.Schema.number(),confidence:aiApi.Schema.number()}})}),totals:aiApi.Schema.object({properties:{kcal:aiApi.Schema.number(),protein_g:aiApi.Schema.number(),carbs_g:aiApi.Schema.number(),fat_g:aiApi.Schema.number()}})}});
    const ai=aiApi.getAI(app,{backend:new aiApi.GoogleAIBackend(),useLimitedUseAppCheckTokens:false});
    const generationConfig={responseMimeType:'application/json',responseSchema:schema,temperature:.15};
    aiModel=aiApi.getGenerativeModel(ai,{model:config.aiModel||'gemini-3.8-flash',generationConfig},{timeout:28000});
    aiFallbackModel=aiApi.getGenerativeModel(ai,{model:'gemini-3.5-flash-lite',generationConfig},{timeout:28000});
  }catch(error){
    console.error('Firebase init:',error);
    document.getElementById('continueOffline').classList.remove('hidden');
    if(!state.onboardingComplete)showOnboarding('auth');
    showToast('Nie udało się połączyć usług Google');
  }
}
document.getElementById('googleSignIn').onclick=async()=>{
  if(!auth||!firebaseAuthApi)return showToast('Logowanie Google nie jest jeszcze gotowe');
  const button=document.getElementById('googleSignIn');
  button.disabled=true;
  try{
    const provider=new firebaseAuthApi.GoogleAuthProvider();
    provider.setCustomParameters({prompt:'select_account'});
    const result=await firebaseAuthApi.signInWithPopup(auth,provider);
    handleAuthUser(result.user);
  }catch(error){
    console.error('Google sign-in:',error);
    const messages={
      'auth/popup-closed-by-user':'Okno logowania zostało zamknięte',
      'auth/popup-blocked':'Przeglądarka zablokowała okno logowania',
      'auth/unauthorized-domain':'Domena aplikacji nie jest dozwolona w Firebase',
      'auth/operation-not-allowed':'Logowanie Google nie jest włączone w Firebase'
    };
    showToast(messages[error.code]||`Błąd logowania: ${error.code||'spróbuj ponownie'}`);
  }finally{
    button.disabled=false;
  }
};
document.getElementById('continueOffline').onclick=()=>{state.offlineMode=true;save();showOnboarding('setup')};
document.getElementById('setupStep').onsubmit=e=>{e.preventDefault();document.getElementById('profileSex').value=document.getElementById('setupSex').value;document.getElementById('profileAge').value=document.getElementById('setupAge').value;document.getElementById('profileHeight').value=document.getElementById('setupHeight').value;document.getElementById('profileWeight').value=document.getElementById('setupWeight').value;document.getElementById('profileActivity').value=document.getElementById('setupActivity').value;const adjustment=Number(document.getElementById('setupGoal').value);document.querySelectorAll('[data-goal]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.goal)===adjustment));const result=calcNeeds();state.profile=result.profile;state.goal=result.target;state.macroGoals={p:result.p,c:result.c,f:result.f};state.weights=[{date:dateKey(today),value:result.profile.weight}];state.onboardingComplete=true;save();hideOnboarding();loadProfile();renderIdentity();renderDashboard();renderProgress();showToast('Twój plan jest gotowy')};
document.getElementById('signOutBtn').onclick=async()=>{if(!auth||!firebaseAuthApi)return;cloudSyncReady=false;clearTimeout(cloudSyncTimer);await firebaseAuthApi.signOut(auth);firebaseUser=null;state=hydrateState({theme:state.theme,accent:state.accent,selectedDate:dateKey(today)});localStorage.setItem('kalorio-state',JSON.stringify(state));refreshApp();showOnboarding('auth');showToast('Wylogowano z konta')};

function calcNeeds(){const sex=document.getElementById('profileSex').value,age=Number(document.getElementById('profileAge').value),height=Number(document.getElementById('profileHeight').value),weight=Number(document.getElementById('profileWeight').value),activity=Number(document.getElementById('profileActivity').value),adjustment=Number(document.querySelector('[data-goal].selected')?.dataset.goal||0);const bmr=10*weight+6.25*height-5*age+(sex==='male'?5:-161),tdee=bmr*activity,target=Math.round((tdee+adjustment)/10)*10,p=Math.round(weight*1.8),f=Math.round(weight*.85),c=Math.max(0,Math.round((target-p*4-f*9)/4));document.getElementById('bmrValue').textContent=`${fmt(bmr)} kcal`;document.getElementById('tdeeValue').textContent=`${fmt(tdee)} kcal`;document.getElementById('goalAdjustment').textContent=`${adjustment>0?'+':''}${fmt(adjustment)} kcal`;document.getElementById('calculatedGoal').textContent=fmt(target);document.getElementById('calcProtein').textContent=`${p} g`;document.getElementById('calcCarbs').textContent=`${c} g`;document.getElementById('calcFat').textContent=`${f} g`;return{target,p,c,f,profile:{sex,age,height,weight,activity,adjustment}}}
function loadProfile(){const p=state.profile;document.getElementById('profileSex').value=p.sex;document.getElementById('profileAge').value=p.age;document.getElementById('profileHeight').value=p.height;document.getElementById('profileWeight').value=p.weight;document.getElementById('profileActivity').value=String(p.activity);document.querySelectorAll('[data-goal]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.goal)===Number(p.adjustment)));calcNeeds()}
document.querySelectorAll('#view-profile input,#view-profile select').forEach(i=>i.addEventListener('input',calcNeeds));document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-goal]').forEach(x=>x.classList.toggle('selected',x===b));calcNeeds()});
document.getElementById('saveProfile').onclick=()=>{const r=calcNeeds();state.profile=r.profile;state.goal=r.target;state.macroGoals={p:r.p,c:r.c,f:r.f};save();renderIdentity();renderDashboard();showToast('Profil i cele zostały zapisane')};
document.getElementById('installHelp').onclick=()=>openModal('infoModal');

function kcalForDate(key){return Object.values(state.diary[key]||{}).flat().reduce((sum,item)=>sum+nutrient(getProduct(item.productId),item.grams,'kcal'),0)}
function renderProgress(){const days=Array.from({length:7},(_,index)=>{const date=new Date(today);date.setDate(today.getDate()-6+index);const key=dateKey(date),kcal=kcalForDate(key);return{date,key,kcal,ratio:state.goal?kcal/state.goal:0,label:date.toLocaleDateString('pl-PL',{weekday:'short'}).slice(0,1).toUpperCase()}}),logged=days.filter(d=>d.kcal>0),avg=days.reduce((sum,d)=>sum+d.kcal,0)/7,onTarget=days.filter(d=>d.ratio>=.9&&d.ratio<=1.1).length,score=Math.round(logged.length/7*100);document.getElementById('weekChart').innerHTML=days.map(d=>`<div class="chart-day"><div class="chart-bar ${d.kcal?'':'empty'}" style="height:${d.kcal?Math.max(8,Math.min(100,d.ratio*82)):0}%"><span>${d.kcal?fmt(d.kcal):'0'}</span></div><small>${d.label}</small></div>`).join('');document.getElementById('currentWeight').textContent=state.weights.length?Number(state.profile.weight).toLocaleString('pl-PL',{minimumFractionDigits:1}):'—';document.getElementById('avgKcal').textContent=fmt(avg);document.getElementById('daysOnTarget').textContent=onTarget;const trend=document.getElementById('weightTrend');if(state.weights.length>1){const change=state.weights.at(-1).value-state.weights[0].value;trend.textContent=`${change>0?'+':''}${one(change)} kg od początku`;trend.classList.toggle('positive',change<=0)}else trend.textContent=state.weights.length?'Pierwszy pomiar zapisany':'Dodaj pierwszy pomiar';let streak=0;for(let i=days.length-1;i>=0&&days[i].kcal>0;i--)streak++;document.getElementById('streakValue').textContent=streak;document.getElementById('streakSide').textContent=streak;document.getElementById('streakHint').textContent=streak?`Tak trzymaj — ${streak}. dzień z rzędu`:'Dodaj pierwszy posiłek';document.getElementById('consistencyScore').textContent=score;document.getElementById('consistencyTitle').textContent=score>=80?'Świetna regularność':score>=50?'Dobry kierunek':'Nowy początek';document.getElementById('consistencyText').textContent=logged.length?`Uzupełniono ${logged.length} z 7 ostatnich dni. Liczy się powtarzalność, nie perfekcja.`:'Dodawaj posiłki każdego dnia, a zobaczysz tutaj swój trend.';document.getElementById('consistencyChecks').innerHTML=days.map(d=>`<span class="${d.kcal?'done':''}">${d.label}</span>`).join('')}
document.getElementById('addWeightBtn').onclick=()=>{const val=prompt('Podaj aktualną masę ciała w kg:',state.profile.weight);if(val===null)return;const num=Number(String(val).replace(',','.'));if(!num||num<30||num>300)return showToast('Podaj prawidłową masę');state.profile.weight=num;state.weights.push({date:dateKey(today),value:num});save();loadProfile();renderProgress();showToast('Pomiar został zapisany')};

document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();switchView('food');setTimeout(()=>document.getElementById('foodSearch').focus(),50)}if(e.key==='Escape')closeModals()});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
loadProfile();renderIdentity();updateDate();renderProducts();renderProgress();initFirebase();

